import datetime
report = api.portal_reports.get(report_id=params["report_id"]) or {}
events = report.get("events") or []
past_events = []
upcoming_events = []
for e in events:
    heading = e.get("heading") or e.get("title") or ""
    body = e.get("body") or e.get("description") or ""
    section = (e.get("section") or e.get("type") or e.get("timing") or e.get("category") or "").lower()
    row = {"heading": heading, "body": body}
    if "past" in section:
        past_events.append(row)
    elif "upcoming" in section or "future" in section:
        upcoming_events.append(row)
    else:
        ev_date = e.get("date") or e.get("event_date")
        is_past = False
        if ev_date:
            try:
                d = datetime.datetime.fromisoformat(str(ev_date).replace("Z", "+00:00"))
                is_past = d.date() < datetime.datetime.utcnow().date()
            except Exception:
                is_past = False
        if is_past:
            past_events.append(row)
        else:
            upcoming_events.append(row)
