rows = api.snapshots.query(portal_id=portal_id, entity_type="attendance", limit=5000) or []

def row_user_key(payload):
    return payload.get("employeeId") or payload.get("employee_id") or payload.get("userId") or payload.get("user_id")

def row_status(payload):
    s = payload.get("status") or payload.get("attendanceStatus") or ""
    return str(s).lower()

def classify(payload):
    status = row_status(payload)
    is_leave = status in ("leave", "on_leave", "onleave") or bool(payload.get("isLeave"))
    is_office = status in ("office", "onsite", "in_office") or payload.get("location") == "office" or bool(payload.get("isOffice"))
    is_present = (not is_leave and status not in ("absent",)) or bool(payload.get("isPresent"))
    return is_present, is_office, is_leave

if not has_attendance_data and rows:
    total = len(rows)
    present_n = 0
    office_n = 0
    leave_n = 0
    for r in rows:
        payload = r.get("payload") or {}
        is_present, is_office, is_leave = classify(payload)
        if is_present:
            present_n += 1
        if is_office:
            office_n += 1
        if is_leave:
            leave_n += 1
    if total > 0:
        attendance_pct = round(present_n / total * 100, 1)
        office_days_pct = round(office_n / total * 100, 1)
        leave_taken_days = float(leave_n)
        has_attendance_data = True

employees = api.employees.list(client_id=client_id) or []
users = api.users.list() or []
