        continue
    user = user_map.get(uid) or {}
    name = user.get("name") or user.get("email") or ""
    emp_rows = [r for r in rows if row_user_key(r.get("payload") or {}) == uid]
    total = len(emp_rows)
    if total > 0:
        present_n = 0
        office_n = 0
        leave_n = 0
        for r in emp_rows:
            payload = r.get("payload") or {}
            is_present, is_office, is_leave = classify(payload)
            if is_present:
                present_n += 1
            if is_office:
                office_n += 1
            if is_leave:
                leave_n += 1
        emp_attendance_pct = round(present_n / total * 100, 1)
        emp_office_days_pct = round(office_n / total * 100, 1)
        emp_leave_taken_days = float(leave_n)
    else:
        emp_attendance_pct = 0.0
        emp_office_days_pct = 0.0
        emp_leave_taken_days = 0.0
    scorecard_rows.append({
        "user_id": uid,
        "name": name,
        "attendance_pct": emp_attendance_pct,
        "office_days_pct": emp_office_days_pct,
        "leave_taken_days": emp_leave_taken_days
    })

has_scorecard_data = len(scorecard_rows) > 0

attendance_pct = attendance_pct or 0.0
